'use strict';
let deskView='music',deskSceneId='',reviewVersionId='',reviewPins=[],compareSelection=['',''],compareFrame=0,tempoTaps=[],deskDrag=null;
const deskTabs={music:'Music & energy',camera:'Camera paths',variety:'Shot variety',continuity:'Continuity',review:'Full-video review',compare:'Compare takes',prompts:'Prompt builder',lookbook:'Lookbook'};
const framingChoices=['Unplanned','Detail','Close-up','Medium close-up','Medium','Two-shot','Wide','Establishing'];
function studioData(){project.studio??={};for(const key of ['continuityCards','cutVersions','reviewNotes','reviewDrafts','lookbook','budgets'])project.studio[key]??=[];project.studio.music??={};project.studio.music.cues??=[];project.studio.music.energy??=[];return project.studio;}
function deskScene(){if(!project.scenes.some(s=>s.id===deskSceneId))deskSceneId=selected||project.scenes[0]?.id;return project.scenes.find(s=>s.id===deskSceneId)||project.scenes[0];}
function shotData(s){s.studio??={};s.studio.camera??={performers:[],points:[]};s.studio.camera.performers??=[];s.studio.camera.points??=[];s.studio.continuity??=[];s.studio.takes??=[];return s.studio;}
function deskPath(s){return 'scenes.'+project.scenes.indexOf(s)+'.studio';}
function deskSelect(label,path,value,values){return `<label>${esc(label)}<select data-path="${path}">${opts(values,value||values[0])}</select></label>`;}
function deskNum(label,path,value,min=0,max=86400,step=.001){return `<label>${esc(label)}<input type="number" data-path="${path}" min="${min}" max="${max}" step="${step}" value="${esc(value??0)}"></label>`;}
function deskButton(label,action,attrs=''){return `<button data-action="${action}" ${attrs}>${esc(label)}</button>`;}
function deskEmpty(text){return `<p class="desk-empty">${esc(text)}</p>`;}
function deskMedia(a,controls=true){if(!a)return '';return a.kind==='image'?`<img class="desk-reference" src="${mediaUrl(a)}" alt="${esc(a.name)}">`:a.kind==='video'?`<video class="desk-reference" src="${mediaUrl(a)}" ${controls?'controls':''} preload="metadata"></video>`:'';}
function deskWarnings(items){return items.length?`<ul class="desk-warnings">${items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'';}
function safeReferenceUrl(url){try{const u=new URL(url);return ['http:','https:'].includes(u.protocol)?u.href:'';}catch{return '';}}
async function deskUpload(file){const owner=project;const res=await fetch('/api/upload',{method:'POST',headers:{'X-Filename':encodeURIComponent(file.name)},body:file});const a=await res.json();if(!res.ok)throw Error(a.error);if(project!==owner)throw Error('Project changed while loading. The file was retained in local media but not assigned.');if(!asset(a.id))owner.assets.push(a);return a;}
function deskChanged(refresh=true){changed();if(refresh)renderDesk();}
function scenePicker(){return `<label class="desk-scene-picker">Working scene<select id="desk-scene">${project.scenes.map((s,i)=>`<option value="${esc(s.id)}" ${deskScene()?.id===s.id?'selected':''}>${i+1} · ${esc(s.title)} (${fmt(s.start)}–${fmt(s.end)})</option>`).join('')}</select></label>`;}
function renderDesk(){
 studioData();cancelAnimationFrame(compareFrame);if(!deskTabs[deskView])deskView='music';
 $('#content').innerHTML=`<div class="section-toolbar"><div><h2>Directing desk</h2><p>Plan the movement. Watch the result. Carry what works into the next video.</p></div></div><nav class="desk-tabs" aria-label="Directing desk views">${Object.entries(deskTabs).map(([key,label])=>`<button class="${deskView===key?'active':''}" data-action="deskView" data-view="${key}">${label}</button>`).join('')}</nav><div class="desk-workspace">${['camera','compare','prompts'].includes(deskView)?scenePicker():''}<div id="desk-panel"></div></div>`;
 ({music:renderMusic,camera:renderCamera,variety:renderVariety,continuity:renderContinuity,review:renderCutReview,compare:renderTakeComparison,prompts:renderPromptBuilder,lookbook:renderLookbook}[deskView])();
}
function musicSvg(){
 const m=studioData().music,d=duration(),grid=StudioCore.beatGrid(m.bpm,m.offset,d),energy=[...m.energy].sort((a,b)=>a.time-b.time);
 return `<svg viewBox="0 0 1000 180" class="music-map" aria-label="Music and visual energy map. Click to add an energy point." data-energy-map role="img"><rect width="1000" height="180" fill="#0c1a20"/>${[1,2,3,4,5].map(v=>`<line x1="0" x2="1000" y1="${150-(v-1)*30}" y2="${150-(v-1)*30}" stroke="#304047"/><text x="4" y="${145-(v-1)*30}">${v}</text>`).join('')}${project.sections.map(s=>`<rect x="${s.start/d*1000}" y="155" width="${(s.end-s.start)/d*1000}" height="25" fill="#24414b"/><text x="${s.start/d*1000+4}" y="173">${esc(s.title)}</text>`).join('')}${grid.filter((_,i)=>grid.length<600||i%4===0).map(b=>`<line x1="${b.time/d*1000}" x2="${b.time/d*1000}" y1="${b.beat%(Number(m.beatsPerBar)||4)===0?0:125}" y2="150" stroke="#52645d" opacity=".45"/>`).join('')}<polyline points="${energy.map(p=>`${p.time/d*1000},${150-(p.energy-1)*30}`).join(' ')}" stroke="#f2bd70" stroke-width="3" fill="none"/>${energy.map(p=>`<circle cx="${p.time/d*1000}" cy="${150-(p.energy-1)*30}" r="5" fill="#f2bd70"><title>${esc(p.label)} · ${fmt(p.time)} · energy ${p.energy}</title></circle>`).join('')}${m.cues.map(c=>`<line x1="${c.time/d*1000}" x2="${c.time/d*1000}" y1="0" y2="150" stroke="#79c1ce"/><circle cx="${c.time/d*1000}" cy="10" r="5" fill="#79c1ce"><title>${esc(c.type)} · ${esc(c.label)} · ${fmt(c.time)}</title></circle>`).join('')}</svg>`;
}
function renderMusic(){const m=studioData().music;
 $('#desk-panel').innerHTML=`<div class="panel"><h3>Follow the song</h3><p>Play the song and mark vocals, fills, builds and breaks. The gold curve is your planned visual energy, from 1 to 5.</p><div class="desk-fields">${deskNum('Tempo (BPM)','studio.music.bpm',m.bpm||120,20,400,1)}${deskNum('First beat offset (seconds)','studio.music.offset',m.offset||0,0,duration())}${deskNum('Beats per bar','studio.music.beatsPerBar',m.beatsPerBar||4,1,16,1)}${deskSelect('Pulse review','studio.music.status',m.status||'draft',['draft','reviewed'])}</div><div class="button-group">${deskButton('Play / pause song','play')}${deskButton('Tap tempo','deskTap')}${deskButton('Suggest pulse from song','deskTempo')}${deskButton('Add cue at playhead','deskCue')}${deskButton('Add energy point','deskEnergy')}</div><p id="tempo-message" class="field-help">The beat grid is a timing guide. Listen and review the tempo and offset before timing camera arrivals to it.</p><div id="music-map-holder">${musicSvg()}</div></div><div class="grid-two"><div class="panel"><h3>Musical cues</h3>${m.cues.map((c,i)=>`<article class="desk-row"><div class="desk-fields">${deskNum('Time (seconds)',`studio.music.cues.${i}.time`,c.time,0,duration())}${deskSelect('Cue type',`studio.music.cues.${i}.type`,c.type,['beat','vocal entrance','fill','build','break','chorus','accent','other'])}${field('Cue',`studio.music.cues.${i}.label`,c.label)}${deskSelect('Review',`studio.music.cues.${i}.status`,c.status,['draft','reviewed'])}</div>${deskButton('Listen here','deskSeek',`data-time="${c.time}"`)} ${deskButton('Remove cue','deskRemove',`data-list="music.cues" data-index="${i}"`)}</article>`).join('')||deskEmpty('No cues yet. Add one while listening.')}</div><div class="panel"><h3>Visual energy</h3><p class="field-help">Click the map to draw points or edit their exact values below. Lower energy should have a story reason.</p>${m.energy.map((p,i)=>`<article class="desk-row"><div class="desk-fields">${deskNum('Time (seconds)',`studio.music.energy.${i}.time`,p.time,0,duration())}${deskNum('Energy (1–5)',`studio.music.energy.${i}.energy`,p.energy,1,5,1)}${field('Story reason / moment',`studio.music.energy.${i}.label`,p.label)}</div>${deskButton('Remove point','deskRemove',`data-list="music.energy" data-index="${i}"`)}</article>`).join('')||deskEmpty('Add the opening, build and payoff you want the audience to feel.')}</div></div>`;
}
function routeSvg(s){const c=shotData(s).camera,people=c.performers,points=c.points;
 return `<svg class="camera-map" viewBox="0 0 600 360" role="img" aria-label="Overhead camera map. Drag performer and camera circles to move them." data-camera-map><defs><pattern id="desk-grid" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M 30 0 L 0 0 0 30" fill="none" stroke="#31434a" stroke-width=".5"/></pattern><marker id="desk-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0 L10 5 L0 10" fill="#f2bd70"/></marker></defs><rect width="600" height="360" fill="#0c1a20"/><rect width="600" height="360" fill="url(#desk-grid)"/>${points.slice(1).map((p,i)=>`<line x1="${points[i].x*6}" y1="${points[i].y*3.6}" x2="${p.x*6}" y2="${p.y*3.6}" stroke="#f2bd70" stroke-width="3" marker-end="url(#desk-arrow)"/>`).join('')}${points.map(p=>{const t=people.find(x=>x.id===p.target);return t?`<line x1="${p.x*6}" y1="${p.y*3.6}" x2="${t.x*6}" y2="${t.y*3.6}" stroke="#7bc4cf" stroke-dasharray="5 5" opacity=".6"/>`:'';}).join('')}${people.map((p,i)=>`<g data-drag-kind="performers" data-index="${i}"><circle cx="${p.x*6}" cy="${p.y*3.6}" r="13" fill="#78bfca"/><text x="${p.x*6}" y="${p.y*3.6-20}" text-anchor="middle">${esc(p.name||'Performer '+(i+1))}</text></g>`).join('')}${points.map((p,i)=>{const same=points.map((q,j)=>Math.abs(q.x-p.x)<.1&&Math.abs(q.y-p.y)<.1?j:-1).filter(j=>j>=0),rank=same.indexOf(i),shared=same.length>1;return `<g data-drag-kind="points" data-index="${i}"><circle cx="${p.x*6}" cy="${p.y*3.6}" r="11" fill="#f2bd70"/>${shared?'':`<text x="${p.x*6}" y="${p.y*3.6+4}" text-anchor="middle" fill="#111">${i+1}</text>`}<text x="${p.x*6}" y="${p.y*3.6+(shared?(rank===0?-20:27+(rank-1)*18):27)}" text-anchor="middle">${shared?(i+1)+' · ':''}${Number(p.time).toFixed(2)}s</text></g>`;}).join('')}</svg>`;
}
function renderCamera(){const s=deskScene();if(!s){$('#desk-panel').innerHTML=deskEmpty('Add a scene first.');return;}const d=shotData(s),p=deskPath(s),c=d.camera;
 $('#desk-panel').innerHTML=`<div class="panel"><h3>One scene, one continuous route</h3><p>Blue circles are performers; gold circles are camera stops. Drag them to position the shot. Dashed lines show attention targets. Coordinates describe an overhead plan, not an automatic 3D reconstruction.</p><div class="button-group">${deskButton('Add performer','deskPerson')}${deskButton('Add camera stop','deskStop')}${deskButton('Preview route','deskRoutePlay')}${deskButton('Confirm timings for this duration','deskRouteConfirm')}</div><div id="camera-map-holder">${routeSvg(s)}</div><div id="route-play-label" class="field-help">Scene length ${(s.end-s.start).toFixed(3)} seconds. Stop times are relative to this scene.</div><div id="route-warnings">${deskWarnings(StudioCore.routeWarnings(s))}</div></div><div class="grid-two"><div class="panel"><h3>Performer blocking</h3>${c.performers.map((t,i)=>`<article class="desk-row"><div class="desk-fields">${field('Performer',`${p}.camera.performers.${i}.name`,t.name)}${deskNum('Left / right (%)',`${p}.camera.performers.${i}.x`,t.x,0,100,1)}${deskNum('Front / back (%)',`${p}.camera.performers.${i}.y`,t.y,0,100,1)}</div>${area('Continuing performance / movement',`${p}.camera.performers.${i}.action`,t.action)}${deskButton('Remove performer','deskCameraRemove',`data-kind="performers" data-index="${i}"`)}</article>`).join('')||deskEmpty('Place each performer and describe what they keep doing as attention moves away.')}</div><div class="panel"><h3>Camera arrivals and handoffs</h3>${c.points.map((t,i)=>`<article class="desk-row"><h4>Stop ${i+1}</h4><div class="desk-fields">${deskNum('Arrival (seconds)',`${p}.camera.points.${i}.time`,t.time,0,s.end-s.start)}${deskNum('Camera X (%)',`${p}.camera.points.${i}.x`,t.x,0,100,1)}${deskNum('Camera Y (%)',`${p}.camera.points.${i}.y`,t.y,0,100,1)}<label>Feature / focus<select data-path="${p}.camera.points.${i}.target"><option value="">Choose performer</option>${c.performers.map(t2=>`<option value="${t2.id}" ${t2.id===t.target?'selected':''}>${esc(t2.name)}</option>`).join('')}</select></label>${deskSelect('Framing',`${p}.camera.points.${i}.framing`,t.framing,framingChoices)}</div>${area('Move, focus shift and musical cue',`${p}.camera.points.${i}.cue`,t.cue)}${deskButton('Remove stop','deskCameraRemove',`data-kind="points" data-index="${i}"`)}</article>`).join('')||deskEmpty('Add starting, handoff and return positions. The route stays inside this scene.')}</div></div><div class="panel"><h3>Scene keyframes</h3><div class="desk-media-grid">${['begin','middle','end'].map(slot=>`<div><h4>${esc(slot)}</h4>${deskMedia(asset(s.media?.[slot]))||deskEmpty('No picture attached.')}${deskButton('Attach '+slot+' picture','attach',`data-id="${s.id}" data-slot="${slot}"`)}</div>`).join('')}</div></div>`;
}
function renderVariety(){const report=StudioCore.variety(project.scenes),d=duration();
 const strip=(label,get)=>`<div class="variety-row"><strong>${label}</strong><div class="variety-strip">${project.scenes.map((s,i)=>`<button style="flex:${(s.end-s.start)/d};min-width:2px" title="Scene ${i+1}: ${esc(get(s))}" data-action="deskOpenScene" data-id="${s.id}" data-view="prompts" class="tone-${get(s).toLowerCase()==='unplanned'?'unplanned':[...get(s)].reduce((n,c)=>n+c.charCodeAt(0),0)%8}">${esc(get(s))}</button>`).join('')}</div></div>`;
 $('#desk-panel').innerHTML=`<div class="panel"><h3>Read the whole sequence</h3><p>Each block follows the scene's duration. Click a block to plan that shot. Unplanned means no choice has been recorded.</p>${strip('Framing',s=>s.studio?.framing||'Unplanned')}${strip('Angle',s=>s.studio?.angle||'Unplanned')}${strip('Movement',StudioCore.shotMotion)}${strip('Scene role',s=>s.lipSync?'Singing':s.role||'Story')}<div class="desk-fields">${project.scenes.map((s,i)=>`<div class="desk-row"><b>${i+1} · ${esc(s.title)}</b>${deskSelect('Framing',`scenes.${i}.studio.framing`,s.studio?.framing,framingChoices)}${deskSelect('Angle',`scenes.${i}.studio.angle`,s.studio?.angle,['Unplanned','Eye level','Low','High','Side','Three-quarter','Over shoulder','Reverse'])}${deskSelect('Camera movement',`scenes.${i}.studio.motion`,s.studio?.motion,['unplanned','moving','static'])}${field('Featured people (comma separated)',`scenes.${i}.studio.featured`,s.studio?.featured)}</div>`).join('')}</div></div><div class="grid-two"><div class="panel"><h3>Coverage questions</h3>${deskWarnings(report.alerts)||deskEmpty('No repetition or long-return alerts from the recorded metadata. Watch the sequence to judge the actual result.')}</div><div class="panel"><h3>Featured screen time</h3>${Object.entries(report.coverage).map(([name,t])=>`<p>${esc(name)} <strong>${t.toFixed(1)} seconds</strong></p>`).join('')||deskEmpty('Assign performers to see their planned coverage.')}<p class="field-help">Shared scenes count for each person. This measures the plan, not detected faces in the footage.</p></div></div>`;
}
function renderContinuity(){const cards=studioData().continuityCards,s=deskScene();
 $('#desk-panel').innerHTML=`<div class="section-toolbar"><div><h3>Visual continuity cards</h3><p>Keep faces, outfits, tattoos, creatures, vehicles and locations beside the scene. These cards do not replace scene pictures or the original identity library.</p></div>${deskButton('Add continuity card','deskCard')}</div>${scenePicker()}<div class="desk-card-grid">${cards.map((c,i)=>{const link=s?.studio?.continuity?.find(x=>x.cardId===c.id),li=s?.studio?.continuity?.indexOf(link);return `<article class="panel"><h3>${esc(c.name||'New continuity card')}</h3>${deskMedia(asset(c.assetId))}<span class="badge">${esc(c.status||'pending')}</span><div class="button-group">${deskButton('Accept','deskCardDecision',`data-index="${i}" data-decision="accepted"`)}${deskButton('Reject','deskCardDecision',`data-index="${i}" data-decision="rejected"`)}${deskButton('Attach reference picture','deskCardImage',`data-index="${i}"`)}</div>${field('Name',`studio.continuityCards.${i}.name`,c.name)}${deskSelect('Type',`studio.continuityCards.${i}.kind`,c.kind,['character','wardrobe','tattoo','vehicle','monster','location','prop'])}${deskSelect('Reference provenance',`studio.continuityCards.${i}.origin`,c.origin,['unknown','original photograph','approved direct photo edit','generated project reference'])}${area('Identity / details to preserve',`studio.continuityCards.${i}.details`,c.details)}${field('Source / provenance note',`studio.continuityCards.${i}.source`,c.source)}<p class="small">Reference hash: ${esc(asset(c.assetId)?.sha256||'No picture attached')}</p>${s?`<div class="desk-row">${deskButton(link?'Unlink from working scene':'Use in working scene','deskCardLink',`data-id="${c.id}"`)}${link?area('State in this scene (damage, wardrobe, position, presence)',`${deskPath(s)}.continuity.${li}.state`,link.state):''}</div>`:''}${deskButton('Remove card','deskRemove',`data-list="continuityCards" data-index="${i}"`)}</article>`;}).join('')||deskEmpty('Add the first visual reference card.')}</div>`;
}
function renderPromptBuilder(){const s=deskScene();if(!s){$('#desk-panel').innerHTML=deskEmpty('Add a scene first.');return;}const d=shotData(s),p=deskPath(s),draft=d.promptDraft,stale=draft&&draft.signature!==StudioCore.sourceSignature(project,s);
 $('#desk-panel').innerHTML=`<div class="grid-two"><div class="panel"><h3>Describe the actual picture</h3><div class="desk-media-grid">${Object.values(s.media||{}).map(asset).filter(a=>a?.kind==='image').map(a=>deskMedia(a)).join('')||deskEmpty('No picture attached.')}</div>${area('Source picture description',p+'.sourceDescription',d.sourceDescription,'Describe what is actually visible, including spatial relationships.')}${field('Confirmed visible people (comma separated)',p+'.visiblePeople',d.visiblePeople,'Georgia Belle, Ruby')}${area('Confirmed visible props',p+'.visibleProps',d.visibleProps)}${area('Sustained performance / practical action',p+'.performance',d.performance,'Describe continuing body movement and complete actions.')}${deskSelect('Framing',p+'.framing',d.framing,framingChoices)}${deskSelect('Angle',p+'.angle',d.angle,['Unplanned','Eye level','Low','High','Side','Three-quarter','Over shoulder','Reverse'])}<div class="button-group">${deskButton('Plan camera route','deskView','data-view="camera"')}${deskButton('Build editable draft','deskBuildPrompt')}</div></div><div class="panel"><h3>Prompt draft</h3><p>This combines your recorded picture description and directing plan. It does not inspect images or submit a generation.</p>${stale?'<div class="notice">The source or plan changed after this draft. Rebuild and review it before use.</div>':''}${draft?deskWarnings(draft.warnings||[]):''}${area('Editable draft',p+'.promptDraft.text',draft?.text||'')}${field('Chosen model / provider for this draft',p+'.promptModel',d.promptModel,'Record your chosen model; no default is selected.')}<div class="button-group">${deskButton('Copy draft','deskCopyPrompt')}${deskButton('Use draft as scene motion prompt','deskApplyPrompt')}</div><p class="field-help">Applying archives the previous motion prompt. Inspect the actual source and confirm provider capabilities before production.</p><details><summary>Exact approved suffix / protected wording</summary>${area('Append verbatim to drafts','studio.protectedSuffix',studioData().protectedSuffix,'Paste the applicable exact wording. This field is not paraphrased.')}</details><h4>Current scene motion prompt</h4><pre class="desk-pre">${esc(s.motionPrompt||'No motion prompt yet.')}</pre></div></div>`;
}
function renderLookbook(){const book=studioData().lookbook;
 $('#desk-panel').innerHTML=`<div class="section-toolbar"><div><h3>Director lookbook & lessons</h3><p>Keep useful references and the reasons a shot worked. Bring selected entries forward from another saved project.</p></div><div class="button-group">${deskButton('Add entry','deskBook')}${deskButton('Save working-scene lesson','deskSceneLesson')}</div></div>${project.scenes.length?scenePicker():''}<div class="panel"><div class="desk-fields"><label>Borrow from a saved project<select id="book-project"><option value="">Choose a project</option>${projects.filter(p=>p.id!==project.id).map(p=>`<option value="${esc(p.id)}">${esc(p.title)}</option>`).join('')}</select></label>${deskButton('Browse its lookbook','deskBrowseBook')}</div><div id="borrow-book"></div></div><div class="desk-card-grid">${book.map((b,i)=>`<article class="panel">${deskMedia(asset(b.assetId))}${field('Title',`studio.lookbook.${i}.title`,b.title)}${deskSelect('Entry type',`studio.lookbook.${i}.kind`,b.kind,['reference','successful shot','lesson'])}${field('Director / creative reference',`studio.lookbook.${i}.director`,b.director)}${field('Reference URL',`studio.lookbook.${i}.url`,b.url)}${safeReferenceUrl(b.url)?`<a href="${esc(safeReferenceUrl(b.url))}" target="_blank" rel="noopener noreferrer">Open reference ↗</a>`:''}${area('What works / lesson',`studio.lookbook.${i}.lesson`,b.lesson)}${area('Camera / performance',`studio.lookbook.${i}.movement`,b.movement)}${area('Light / color',`studio.lookbook.${i}.lightColor`,b.lightColor)}<div class="button-group">${deskButton('Attach picture or clip','deskBookMedia',`data-index="${i}"`)}${deskButton('Apply to director notes','deskBookApply',`data-index="${i}"`)}${deskButton('Remove entry','deskRemove',`data-list="lookbook" data-index="${i}"`)}</div>${b.sourceProject?`<p class="small">From ${esc(b.sourceProject)}</p>`:''}</article>`).join('')||deskEmpty('Save a reference or a lesson from an approved take.')}</div>`;
}
function captureReviewDraft(){const v=activeCut();if(!v||!$('#review-draft'))return;const sd=studioData();let draft=sd.reviewDrafts.find(d=>d.id===v.id);if(!draft){draft={id:v.id};sd.reviewDrafts.push(draft);}Object.assign(draft,{text:$('#review-draft').value,time:Number($('#review-time').value)||0,endTime:$('#review-end').value,annotations:structuredClone(reviewPins)});changed();}
function activeCut(){const cuts=studioData().cutVersions;if(!cuts.some(v=>v.id===reviewVersionId))reviewVersionId=cuts.at(-1)?.id||'';return cuts.find(v=>v.id===reviewVersionId);}
function reviewPinSvg(pins){return pins.map(p=>`<ellipse cx="${p.x*1000}" cy="${p.y*1000}" rx="${p.rx*1000}" ry="${p.ry*1000}" fill="none" stroke="#ffdd55" stroke-width="4" vector-effect="non-scaling-stroke"/>`).join('');}
function renderCutReview(){const sd=studioData(),v=activeCut(),a=asset(v?.assetId),notes=sd.reviewNotes.filter(n=>n.versionId===v?.id);const draft=sd.reviewDrafts.find(d=>d.id===v?.id)||{};reviewPins=structuredClone(draft.annotations||[]);
 $('#desk-panel').innerHTML=`<div class="section-toolbar"><div><h3>Review the assembled video</h3><p>Comments retain this cut's exact asset hash, time and scene map. Scene timing changes later do not move old notes.</p></div>${deskButton('Load a full video version','deskLoadCut')}</div>${v?`<div class="desk-fields"><label>Video version<select id="cut-version">${sd.cutVersions.map(v2=>`<option value="${v2.id}" ${v2.id===v.id?'selected':''}>${esc(v2.label)}</option>`).join('')}</select></label>${field('Version label',`studio.cutVersions.${sd.cutVersions.indexOf(v)}.label`,v.label)}${deskNum('Song time at video start (seconds)',`studio.cutVersions.${sd.cutVersions.indexOf(v)}.offset`,v.offset||0,-86400,86400)}</div><div class="desk-review-layout"><div class="panel"><div class="review-stage"><video id="cut-player" src="${mediaUrl(a)}" controls preload="metadata"></video><svg id="review-overlay" viewBox="0 0 1000 1000" preserveAspectRatio="none" aria-label="Draw a circle on the paused frame">${reviewPinSvg(reviewPins)}</svg></div><div class="button-group">${deskButton('Circle a problem','deskAnnotate')}${deskButton('Clear circles','deskClearPins')}${deskButton('Use current frame','deskReviewTime')}</div><p id="review-position">Play or seek the video, then pause to leave a note.</p><label>Note<textarea id="review-draft" placeholder="What should we fix or preserve?">${esc(draft.text||'')}</textarea></label><div class="desk-fields"><label>From (video seconds)<input id="review-time" type="number" min="0" step="0.001" value="${Number(draft.time)||0}"></label><label>To (optional video seconds)<input id="review-end" type="number" min="0" step="0.001" value="${esc(draft.endTime??'')}"></label></div><div class="button-group">${deskButton('Seek to entered time','deskSeekReview')}${deskButton('Save note at this frame','deskSaveReview')}</div><p class="small">SHA-256: ${esc(v.sha256)} · ${(v.sceneMap||[]).length} scene timings captured for this cut.</p></div><div class="panel"><h3>Version notes · ${notes.length}</h3>${notes.map(n=>{const i=sd.reviewNotes.indexOf(n);return `<article class="desk-row"><h4>${fmt(n.time)}${n.endTime?`–${fmt(n.endTime)}`:''} · ${esc(n.sceneNumber?'Scene '+n.sceneNumber:'Outside mapped scenes')}</h4><p>${esc(n.sceneTitle||'')}</p>${area('Review note',`studio.reviewNotes.${i}.text`,n.text)}${deskSelect('Repair status',`studio.reviewNotes.${i}.status`,n.status,['open','in progress','awaiting review','resolved'])}<div class="button-group">${deskButton('Jump to note','deskJumpReview',`data-id="${n.id}"`)}${deskButton('Remove note','deskRemove',`data-list="reviewNotes" data-index="${i}"`)}</div><p class="small">${n.annotations?.length||0} circle(s) saved with this frame.</p></article>`;}).join('')||deskEmpty('No notes on this version yet.')}</div></div>`:deskEmpty('Load the assembled MP4 to review pacing and flag exact frames.')}`;
 const video=$('#cut-player');if(video){video.addEventListener('loadedmetadata',()=>{if(draft.time){video.currentTime=Math.min(draft.time,video.duration);video.addEventListener('seeked',()=>{$('#review-overlay').innerHTML=reviewPinSvg(reviewPins);},{once:true});}});video.addEventListener('timeupdate',()=>{const s=StudioCore.atScene(v.sceneMap||[],video.currentTime+Number(v.offset||0));$('#review-position').textContent=`Video ${fmt(video.currentTime)} · ${s?'Scene '+((v.sceneMap||[]).indexOf(s)+1)+' · '+s.title:'Outside the captured scene map'}`;});video.addEventListener('pause',()=>{if($('#review-time'))$('#review-time').value=video.currentTime.toFixed(3);if($('#review-draft')?.value)captureReviewDraft();});video.addEventListener('seeked',()=>{if(!$('#review-overlay').classList.contains('drawing'))$('#review-overlay').innerHTML='';});video.addEventListener('play',()=>{reviewPins=[];$('#review-overlay').innerHTML='';$('#review-overlay').classList.remove('drawing');pauseAudio();});}
}
function sceneTakes(s){const takes=[...(s.studio?.takes||[])],a=asset(s.media?.clip);if(a&&!takes.some(t=>t.assetId===a.id))takes.unshift({id:'current-'+a.id,label:'Current scene clip',assetId:a.id,sha256:a.sha256,startOffset:0,status:'pending',existing:true});return takes;}
function selectedTakes(s){const takes=sceneTakes(s);for(let i=0;i<2;i++)if(!takes.some(t=>t.id===compareSelection[i]))compareSelection[i]=takes[i]?.id||takes[0]?.id||'';return compareSelection.map(tid=>takes.find(t=>t.id===tid));}
function renderTakeComparison(){const s=deskScene();if(!s){$('#desk-panel').innerHTML=deskEmpty('Add a scene first.');return;}shotData(s);const takes=sceneTakes(s),pair=selectedTakes(s);
 $('#desk-panel').innerHTML=`<div class="section-toolbar"><div><h3>Compare exact takes</h3><p>Align the retained action using each take's source in-point. Decisions remain tied to the specific video hash.</p></div>${deskButton('Add video take','deskTake')}</div><div class="compare-grid">${pair.map((t,i)=>`<div class="panel"><label>${i?'Right take':'Left take'}<select data-compare-select="${i}"><option value="">Choose take</option>${takes.map(t2=>`<option value="${t2.id}" ${t2.id===t?.id?'selected':''}>${esc(t2.label)} · ${esc(t2.status)}</option>`).join('')}</select></label>${t?`<div class="compare-window"><video id="take-${i}" src="${mediaUrl(asset(t.assetId))}" muted playsinline preload="metadata"></video></div><div class="desk-fields"><label>Source in-point (seconds)<input type="number" min="0" step=".001" value="${t.startOffset||0}" data-take-offset="${t.id}"></label><label>View scale<input type="range" min="1" max="4" step=".1" value="1" data-take-zoom="${i}"></label><label>View center X (%)<input type="range" min="0" max="100" value="50" data-take-pan-x="${i}"></label><label>View center Y (%)<input type="range" min="0" max="100" value="35" data-take-pan-y="${i}"></label></div><p class="field-help">View magnification only; no sharpening or texture changes.</p><span class="badge">${esc(t.status)}</span><div class="button-group">${deskButton('Accept','deskTakeDecision',`data-id="${t.id}" data-decision="accepted"`)}${deskButton('Reject','deskTakeDecision',`data-id="${t.id}" data-decision="rejected"`)}${deskButton('Use accepted take in scene','deskUseTake',`data-id="${t.id}" ${StudioCore.canUseTake(t,asset(t.assetId))?'':'disabled'}`)}</div><p class="small">${esc(asset(t.assetId)?.name)}<br>SHA-256: ${esc(t.sha256)}</p>`:deskEmpty('Attach a take to compare.')}</div>`).join('')}</div><div class="panel"><div class="button-group">${deskButton('Play both','deskComparePlay')}${deskButton('Pause both','deskComparePause')}${deskButton('Restart both','deskCompareRestart')}</div><label>Shared playback position<input id="compare-scrub" type="range" min="0" max="${s.end-s.start}" step=".01" value="0"></label><p id="compare-clock" class="small">00:00.000 · audio muted for visual comparison</p></div>`;
 pair.forEach((t,i)=>{const v=$('#take-'+i);if(v)v.addEventListener('loadedmetadata',()=>{v.currentTime=Math.min(Number(t.startOffset)||0,v.duration);});});
}
function renderStudioProduction(){const sd=studioData(),reports=StudioCore.budgetReport(sd.budgets,project.jobs),repairs=sd.reviewNotes.filter(n=>n.status!=='resolved');
 $('#content').innerHTML=`<div class="section-toolbar"><div><h2>Production & repairs</h2><p>Keep provider budgets separate and track the exact take that needs work.</p></div><div class="button-group">${deskButton('Add budget','deskBudget')}${deskButton('Track a job','addJob')}</div></div><div class="notice">A local planning ledger. Balances and charges are entered from provider receipts; this screen does not purchase credits or submit jobs.</div><div class="desk-card-grid">${reports.map((b,i)=>`<article class="panel"><h3>${esc(b.name||'New budget')} · ${esc(b.provider)}</h3><p class="budget-stat">${b.actual} charged + ${b.planned} estimated<br><strong>${b.remaining} of ${Number(b.ceiling)||0} credits uncommitted</strong></p>${deskWarnings([...(b.remaining<0?['This budget is over its ceiling.']:[]),...(b.mismatch?[`${b.mismatch} job(s) use a different provider and are excluded from this total. Correct their assignment.`]:[]),...(b.unknown?[`${b.unknown} failed job(s) have unconfirmed charges. Check the provider receipt.`]:[])])}<div class="desk-fields">${field('Batch name',`studio.budgets.${i}.name`,b.name)}${deskSelect('Provider',`studio.budgets.${i}.provider`,b.provider,['Kling','HeyGen','Magnific (pictures only)','Other'])}${field('Chosen model',`studio.budgets.${i}.model`,b.model)}${field('Chosen resolution / quality',`studio.budgets.${i}.resolution`,b.resolution)}${deskNum('Budget ceiling',`studio.budgets.${i}.ceiling`,b.ceiling,0,100000000,1)}${deskNum('Reported provider balance',`studio.budgets.${i}.balance`,b.balance,0,100000000,1)}${field('Balance checked at',`studio.budgets.${i}.balanceAsOf`,b.balanceAsOf)}${deskSelect('Approval record',`studio.budgets.${i}.approval`,b.approval,['not approved','approved'])}</div>${area('Approval / limits / receipt notes',`studio.budgets.${i}.notes`,b.notes)}</article>`).join('')||deskEmpty('Add a separate budget for each provider and approved batch.')}</div><div class="panel"><h3>Jobs</h3>${project.jobs.map((j,i)=>`<article class="desk-row"><div class="desk-fields"><label>Scene<select data-path="jobs.${i}.sceneId"><option value="">Unassigned</option>${project.scenes.map((s,n)=>`<option value="${s.id}" ${s.id===j.sceneId?'selected':''}>${n+1} · ${esc(s.title)}</option>`).join('')}</select></label><label>Budget batch<select data-path="jobs.${i}.budgetId"><option value="">Unassigned</option>${sd.budgets.map(b=>`<option value="${b.id}" ${b.id===j.budgetId?'selected':''}>${esc(b.name)} · ${esc(b.provider)}</option>`).join('')}</select></label>${deskSelect('Provider',`jobs.${i}.provider`,j.provider,['Kling','HeyGen','Magnific (pictures only)','Other'])}${field('Model',`jobs.${i}.model`,j.model)}${field('Resolution',`jobs.${i}.resolution`,j.resolution)}${deskNum('Generated seconds (including handles)',`jobs.${i}.generatedDuration`,j.generatedDuration)}${deskNum('Handle seconds included',`jobs.${i}.handles`,j.handles)}${deskNum('Estimated credits',`jobs.${i}.estimatedCredits`,j.estimatedCredits,0,100000000,1)}${deskNum('Actual credits charged',`jobs.${i}.credits`,j.credits,0,100000000,1)}<label class="inline-check"><input type="checkbox" data-path="jobs.${i}.chargeRecorded" ${j.chargeRecorded===true||(j.chargeRecorded===undefined&&Number(j.credits)>0)?'checked':''}>Charge verified, including zero</label>${deskSelect('Status',`jobs.${i}.status`,j.status,['planned','submitted','running','review','approved','failed'])}${field('Provider job ID',`jobs.${i}.jobId`,j.jobId)}${field('Result URL',`jobs.${i}.url`,j.url)}</div>${area('Notes / receipt / retry authorization',`jobs.${i}.notes`,j.notes)}${deskButton('Remove job','deleteJob',`data-index="${i}"`)}</article>`).join('')||deskEmpty('No jobs recorded.')}</div><div class="panel"><h3>Repair queue · ${repairs.length} open</h3>${repairs.map(n=>{const v=sd.cutVersions.find(v=>v.id===n.versionId),i=sd.reviewNotes.indexOf(n);return `<article class="desk-row"><b>${esc(v?.label||'Missing video version')} · ${fmt(n.time)} · ${esc(n.sceneTitle||'Unmapped scene')}</b><p>${esc(n.text)}</p>${deskSelect('Repair status',`studio.reviewNotes.${i}.status`,n.status,['open','in progress','awaiting review','resolved'])}${deskButton('Open exact frame','deskRepair',`data-id="${n.id}"`)}</article>`;}).join('')||deskEmpty('No unresolved full-video review notes.')}<details><summary>Existing scene review notes</summary>${project.scenes.filter(s=>s.reviewNotes).map(s=>`<p><b>${esc(s.title)}</b><br>${esc(s.reviewNotes)}</p>`).join('')||'<p>No scene review notes.</p>'}</details></div>`;
}
function materializeTake(s,tid){const list=shotData(s).takes;let t=list.find(t=>t.id===tid);if(!t){const existing=sceneTakes(s).find(t=>t.id===tid);if(!existing)throw Error('Take not found.');t={...existing};delete t.existing;list.push(t);}return t;}
function pauseCompare(){cancelAnimationFrame(compareFrame);for(let i=0;i<2;i++)$('#take-'+i)?.pause();}
function alignCompare(time){const pair=selectedTakes(deskScene());pair.forEach((t,i)=>{const v=$('#take-'+i);if(v&&t&&Number.isFinite(v.duration))v.currentTime=Math.min(v.duration,Math.max(0,time+Number(t.startOffset||0)));});if($('#compare-scrub'))$('#compare-scrub').value=time;}
async function playCompare(){const pair=selectedTakes(deskScene()),left=$('#take-0'),right=$('#take-1');if(!left||!right)throw Error('Choose a take on both sides.');if(!Number.isFinite(left.duration)||!Number.isFinite(right.duration)||Number(pair[0].startOffset||0)>=left.duration||Number(pair[1].startOffset||0)>=right.duration)throw Error('Wait for both videos to load and choose in-points before their ends.');pauseAudio();const time=Math.max(0,left.currentTime-Number(pair[0].startOffset||0));alignCompare(time);await Promise.all([left.play(),right.play()]);const tick=()=>{if(!left.isConnected||!right.isConnected)return;const local=left.currentTime-Number(pair[0].startOffset||0),limit=Math.min(deskScene().end-deskScene().start,left.duration-Number(pair[0].startOffset||0),right.duration-Number(pair[1].startOffset||0));if(local>=limit||left.ended||right.ended){pauseCompare();return;}if(Math.abs(right.currentTime-Number(pair[1].startOffset||0)-local)>.08)right.currentTime=local+Number(pair[1].startOffset||0);$('#compare-scrub').max=Math.max(0,limit);$('#compare-scrub').value=Math.max(0,local);$('#compare-clock').textContent=fmt(local)+' · synchronized visual comparison';compareFrame=requestAnimationFrame(tick);};cancelAnimationFrame(compareFrame);compareFrame=requestAnimationFrame(tick);}
function studioSceneShortcut(s){return `<section class="inspector-section"><h3>Directing desk</h3><p class="field-help">Draw this scene's camera path, compare takes or build a prompt from its current references.</p><div class="button-group">${deskButton('Camera path','deskOpenScene',`data-id="${s.id}" data-view="camera"`)}${deskButton('Prompt builder','deskOpenScene',`data-id="${s.id}" data-view="prompts"`)}${deskButton('Compare takes','deskOpenScene',`data-id="${s.id}" data-view="compare"`)}</div></section>`;}
function initStudio(){
 renderProduction=renderStudioProduction;
 Object.assign(actions,{
  deskView:el=>{pauseCompare();deskView=el.dataset.view;project.view.deskView=deskView;changed();reviewPins=[];renderDesk();},
  deskOpenScene:el=>{pauseCompare();if($('#dialog').open)closeModal();deskSceneId=el.dataset.id;selected=el.dataset.id;deskView=el.dataset.view||'camera';tab='desk';changed();renderTabs();renderContent();},
  deskSeek:el=>{audio.currentTime=Number(el.dataset.time);playAudio();},
  deskCue:()=>{studioData().music.cues.push({id:id(),time:Math.min(duration(),audio.currentTime||0),type:'accent',label:'',status:'draft'});deskChanged();},
  deskEnergy:()=>{studioData().music.energy.push({id:id(),time:Math.min(duration(),audio.currentTime||0),energy:4,label:''});deskChanged();},
  deskTap:()=>{const t=performance.now();if(tempoTaps.length&&t-tempoTaps.at(-1)>2500)tempoTaps=[];tempoTaps.push(t);tempoTaps=tempoTaps.slice(-9);if(tempoTaps.length>2){const bpm=Math.round(60000*(tempoTaps.length-1)/(t-tempoTaps[0]));if(bpm>=20&&bpm<=400){studioData().music.bpm=bpm;studioData().music.status='draft';deskChanged();$('#tempo-message').textContent=`Tapped tempo: ${bpm} BPM. Keep tapping or review against the song.`;}}},
  deskTempo:async el=>{if(!project.song)throw Error('Load a song first.');const pid=project.id,songId=project.song;el.disabled=true;$('#tempo-message').textContent='Analyzing the local song for a candidate pulse…';let context;try{context=new AudioContext();const buffer=await context.decodeAudioData(await (await fetch(mediaUrl(asset(songId)))).arrayBuffer());const bpm=StudioCore.estimateTempo(buffer.getChannelData(0),buffer.sampleRate);if(project.id!==pid)return;studioData().music.bpm=bpm;studioData().music.status='draft';changed();if(tab==='desk'&&deskView==='music'){renderDesk();$('#tempo-message').textContent=`Suggested pulse: ${bpm} BPM. This can be half/double the musical tempo. Listen, adjust the first-beat offset and mark reviewed when correct.`;}}finally{await context?.close();el.disabled=false;}},
  deskRemove:el=>{const path=el.dataset.list.split('.');let list=studioData();for(const k of path)list=list[k];if(!Array.isArray(list))return;rememberEdit();list.splice(Number(el.dataset.index),1);deskChanged();},
  deskPerson:()=>{const s=deskScene();if(!s)return;const d=shotData(s);d.camera.performers.push({id:id(),name:'Performer '+(d.camera.performers.length+1),x:25+d.camera.performers.length*15%60,y:35,action:''});deskChanged();},
  deskStop:()=>{const s=deskScene();if(!s)return;const d=shotData(s),n=d.camera.points.length;d.routeDuration=s.end-s.start;d.camera.points.push({id:id(),time:n?Math.min(s.end-s.start,(d.camera.points.at(-1).time||0)+1):0,x:20+n*20%65,y:80,target:'',framing:'Medium',cue:''});deskChanged();},
  deskCameraRemove:el=>{const s=deskScene(),c=shotData(s).camera;rememberEdit();c[el.dataset.kind].splice(Number(el.dataset.index),1);deskChanged();},
  deskRouteConfirm:()=>{const s=deskScene(),warnings=StudioCore.routeWarnings(s).filter(w=>!w.startsWith('Scene duration'));if(warnings.length)throw Error(warnings.join(' '));shotData(s).routeDuration=s.end-s.start;deskChanged();},
  deskRoutePlay:()=>{const s=deskScene(),points=shotData(s).camera.points;if(points.length<2)throw Error('Add at least two camera stops.');const warnings=StudioCore.routeWarnings(s);if(warnings.length)throw Error(warnings.join(' '));const svg=$('[data-camera-map]'),marker=document.createElementNS('http://www.w3.org/2000/svg','circle');marker.setAttribute('r','7');marker.setAttribute('fill','#fff');svg.append(marker);const start=performance.now(),len=s.end-s.start;const tick=()=>{if(!marker.isConnected)return;const t=(performance.now()-start)/1000;if(t>len){marker.remove();return;}let a=points[0],b=points[0];for(let i=1;i<points.length;i++)if(t>=points[i-1].time){a=points[i-1];b=points[i];if(t<=b.time)break;}const f=b.time===a.time?0:StudioCore.clamp((t-a.time)/(b.time-a.time),0,1);marker.setAttribute('cx',(a.x+(b.x-a.x)*f)*6);marker.setAttribute('cy',(a.y+(b.y-a.y)*f)*3.6);$('#route-play-label').textContent=fmt(t)+' · camera path preview (diagram only)';requestAnimationFrame(tick);};requestAnimationFrame(tick);},
  deskCard:()=>{studioData().continuityCards.push({id:id(),name:'',kind:'character',origin:'unknown',details:'',status:'pending',decisions:[]});deskChanged();},
  deskCardImage:el=>{const card=studioData().continuityCards[Number(el.dataset.index)],pid=project.id;pickFile('image/*',async file=>{const a=await deskUpload(file);if(project.id!==pid)throw Error('Project changed while attaching.');if(a.kind!=='image')throw Error('Choose a picture.');card.history??=[];if(card.assetId)card.history.push({assetId:card.assetId,sha256:card.sha256,status:card.status,at:new Date().toISOString()});card.assetId=a.id;card.sha256=a.sha256;card.status='pending';deskChanged();});},
  deskCardDecision:el=>{const c=studioData().continuityCards[Number(el.dataset.index)],a=asset(c.assetId);if(!a)throw Error('Attach the reference picture first.');c.status=el.dataset.decision;c.sha256=a.sha256;c.decisions??=[];c.decisions.push({status:c.status,assetId:a.id,sha256:a.sha256,at:new Date().toISOString()});deskChanged();},
  deskCardLink:el=>{const s=deskScene();if(!s)return;const d=shotData(s),i=d.continuity.findIndex(x=>x.cardId===el.dataset.id);if(i>=0)d.continuity.splice(i,1);else d.continuity.push({id:id(),cardId:el.dataset.id,state:''});deskChanged();},
  deskBuildPrompt:()=>{const s=deskScene();if(!s)return;const d=shotData(s);if(d.promptDraft?.text){d.draftHistory??=[];d.draftHistory.push({...d.promptDraft,archivedAt:new Date().toISOString()});}d.promptDraft={...StudioCore.draftPrompt(project,s),createdAt:new Date().toISOString()};deskChanged();},
  deskCopyPrompt:async()=>{const text=deskScene()?.studio?.promptDraft?.text;if(!text)throw Error('Build a draft first.');await navigator.clipboard.writeText(text);toast('Draft copied.');},
  deskApplyPrompt:()=>{const s=deskScene(),draft=s?.studio?.promptDraft;if(!draft?.text)throw Error('Build a draft first.');if(draft.signature!==StudioCore.sourceSignature(project,s))throw Error('The scene changed. Rebuild the draft before applying it.');s.promptHistory??=[];if(s.motionPrompt)s.promptHistory.push({prompt:s.motionPrompt,media:{...s.media},reason:'Replaced from Directing desk',at:new Date().toISOString()});s.motionPrompt=draft.text;s.motionPromptStatus='draft';deskChanged();toast('Draft placed in the scene. Previous prompt retained.');},
  deskBook:()=>{studioData().lookbook.push({id:id(),title:'',kind:'reference',director:'',lesson:'',movement:'',lightColor:''});deskChanged();},
  deskSceneLesson:()=>{const s=deskScene();if(!s)throw Error('Choose a working scene first.');studioData().lookbook.push({id:id(),title:s.title,kind:'lesson',director:project.direction?.director||'',sceneId:s.id,assetId:s.media?.clip||s.media?.begin||'',lesson:'',movement:(s.techniques||[]).filter(t=>t.category==='camera').map(t=>t.directions||t.title).join('\n'),lightColor:[project.direction?.lighting,project.direction?.colors].filter(Boolean).join('\n')});deskChanged();},
  deskBookMedia:el=>{const entry=studioData().lookbook[Number(el.dataset.index)],pid=project.id;pickFile('image/*,video/*',async file=>{const a=await deskUpload(file);if(project.id!==pid)throw Error('Project changed while attaching.');entry.assetId=a.id;entry.sha256=a.sha256;deskChanged();});},
  deskBookApply:el=>{const b=studioData().lookbook[Number(el.dataset.index)];rememberEdit();project.studio.directionHistory??=[];project.studio.directionHistory.push({...project.direction,at:new Date().toISOString()});if(b.director)project.direction.director=b.director;project.direction.directorStyle=[project.direction.directorStyle,`Reference: ${b.title}`,[b.lesson,b.movement,b.lightColor].filter(Boolean).join('\n')].filter(Boolean).join('\n\n');changed();render();toast('Reference appended to director notes. Previous direction retained.');},
  deskBrowseBook:async()=>{const pid=$('#book-project').value;if(!pid)throw Error('Choose a saved project.');const r=await api('/api/projects/'+pid);window.borrowedBook=r.state;$('#borrow-book').innerHTML=(r.state.studio?.lookbook||[]).map((b,i)=>`<div class="desk-row"><b>${esc(b.title)}</b><p>${esc(b.lesson)}</p>${deskButton('Bring this entry into this project','deskBorrow',`data-index="${i}"`)}</div>`).join('')||deskEmpty('This project has no lookbook entries yet.');},
  deskBorrow:el=>{const source=window.borrowedBook,b=source?.studio?.lookbook?.[Number(el.dataset.index)];if(!b)throw Error('Browse the source again.');if(studioData().lookbook.some(x=>x.sourceEntryId===b.id&&x.sourceProjectId===source.id))throw Error('This entry has already been brought into this project.');const a=source.assets.find(a=>a.id===b.assetId);if(a&&!asset(a.id))project.assets.push(structuredClone(a));studioData().lookbook.push({...structuredClone(b),id:id(),sourceEntryId:b.id,sourceProjectId:source.id,sourceProject:source.title});deskChanged();},
  deskLoadCut:()=>{const pid=project.id;pickFile('video/*',async file=>{const a=await deskUpload(file);if(project.id!==pid)throw Error('Project changed while loading.');if(a.kind!=='video')throw Error('Choose a video file.');const v={id:id(),label:file.name,assetId:a.id,sha256:a.sha256,offset:0,createdAt:new Date().toISOString(),sceneMap:project.scenes.map((s,i)=>({id:s.id,title:s.title,start:s.start,end:s.end,number:i+1}))};studioData().cutVersions.push(v);reviewVersionId=v.id;reviewPins=[];deskChanged();});},
  deskAnnotate:()=>{const v=$('#cut-player');if(!v)throw Error('Load a video version first.');v.pause();$('#review-time').value=v.currentTime.toFixed(3);$('#review-overlay').classList.toggle('drawing');toast('Drag a circle around the problem. Click Circle a problem again to return to playback.');},
  deskClearPins:()=>{reviewPins=[];$('#review-overlay').innerHTML='';captureReviewDraft();},
  deskReviewTime:()=>{const v=$('#cut-player');v.pause();$('#review-time').value=v.currentTime.toFixed(3);reviewPins=[];$('#review-overlay').innerHTML='';captureReviewDraft();},
  deskSeekReview:()=>{const v=$('#cut-player'),t=Number($('#review-time').value);if(!Number.isFinite(t)||t<0||t>v.duration)throw Error('Enter a time inside this video.');v.pause();v.currentTime=t;reviewPins=[];$('#review-overlay').innerHTML='';},
  deskSaveReview:()=>{const v=activeCut(),text=$('#review-draft').value.trim(),time=Number($('#review-time').value),end=$('#review-end').value===''?null:Number($('#review-end').value),player=$('#cut-player');if(!text)throw Error('Write the note first.');if(!Number.isFinite(time)||time<0||time>player.duration||(end!==null&&(!Number.isFinite(end)||end<time||end>player.duration)))throw Error('Use a valid time or range inside this video.');const s=StudioCore.atScene(v.sceneMap||[],time+Number(v.offset||0));studioData().reviewNotes.push({id:id(),versionId:v.id,assetId:v.assetId,sha256:v.sha256,time,endTime:end,sceneId:s?.id||'',sceneTitle:s?.title||'',sceneNumber:s?(s.number||(v.sceneMap||[]).indexOf(s)+1):0,text,status:'open',annotations:structuredClone(reviewPins),createdAt:new Date().toISOString()});studioData().reviewDrafts=studioData().reviewDrafts.filter(d=>d.id!==v.id);reviewPins=[];deskChanged();},
  deskJumpReview:el=>{const n=studioData().reviewNotes.find(n=>n.id===el.dataset.id),video=$('#cut-player');video.pause();const show=()=>{$('#review-overlay').innerHTML=reviewPinSvg(n.annotations||[]);};video.addEventListener('seeked',show,{once:true});video.currentTime=n.time;$('#review-time').value=n.time;show();},
  deskTake:()=>{const s=deskScene(),pid=project.id;if(!s)return;pickFile('video/*',async file=>{const a=await deskUpload(file);if(project.id!==pid)throw Error('Project changed while loading.');if(a.kind!=='video')throw Error('Choose a video file.');shotData(s).takes.push({id:id(),label:file.name,assetId:a.id,sha256:a.sha256,startOffset:0,status:'pending',decisions:[]});deskChanged();});},
  deskTakeDecision:el=>{const t=materializeTake(deskScene(),el.dataset.id),a=asset(t.assetId);if(!a||a.sha256!==t.sha256)throw Error('The recorded take does not match the current asset. Reattach it for review.');t.status=el.dataset.decision;t.decisions??=[];t.decisions.push({status:t.status,sha256:a.sha256,assetId:a.id,at:new Date().toISOString()});deskChanged();},
  deskUseTake:el=>{const s=deskScene(),t=materializeTake(s,el.dataset.id),a=asset(t.assetId);if(!StudioCore.canUseTake(t,a))throw Error('Accept this exact take first.');rememberEdit();s.replacements??=[];s.replacements.push({slot:'clip',oldAsset:s.media?.clip||null,newAsset:a.id,at:new Date().toISOString(),takeId:t.id});s.media??={};s.media.clip=a.id;s.studio.selectedTakeId=t.id;s.studio.clipIn=t.startOffset||0;changed();renderDesk();toast('Accepted take assigned to this scene; the previous file is retained.');},
  deskComparePlay:playCompare,deskComparePause:pauseCompare,deskCompareRestart:()=>{pauseCompare();alignCompare(0);},
  deskBudget:()=>{studioData().budgets.push({id:id(),name:'',provider:'Kling',model:'',resolution:'',ceiling:0,balance:0,balanceAsOf:'',approval:'not approved',notes:''});changed();renderProduction();},
  deskRepair:el=>{const n=studioData().reviewNotes.find(n=>n.id===el.dataset.id);reviewVersionId=n.versionId;tab='desk';deskView='review';changed();renderTabs();renderContent();const v=$('#cut-player');if(v){v.addEventListener('loadedmetadata',()=>actions.deskJumpReview(el),{once:true});if(v.readyState>=1)actions.deskJumpReview(el);}}
 });
}
document.addEventListener('change',e=>{
 const el=e.target;if(!project)return;
 if(el.id==='desk-scene'){deskSceneId=el.value;project.view.deskSceneId=deskSceneId;changed();renderDesk();}
 if(el.id==='cut-version'){reviewVersionId=el.value;reviewPins=[];changed();renderCutReview();}
 if(el.dataset.compareSelect!==undefined){pauseCompare();compareSelection[Number(el.dataset.compareSelect)]=el.value;renderTakeComparison();}
 if(el.dataset.takeOffset){pauseCompare();const n=Number(el.value);if(!Number.isFinite(n)||n<0){toast('Use a non-negative source in-point.');return;}materializeTake(deskScene(),el.dataset.takeOffset).startOffset=n;changed();alignCompare(0);}
 const path=el.dataset.path||'';
 if(path.startsWith('studio.music.')&&$('#music-map-holder'))$('#music-map-holder').innerHTML=musicSvg();
 if(path.includes('.studio.camera.')&&$('#camera-map-holder')){$('#camera-map-holder').innerHTML=routeSvg(deskScene());$('#route-warnings').innerHTML=deskWarnings(StudioCore.routeWarnings(deskScene()));}
 if(tab==='desk'&&deskView==='variety'&&path.includes('.studio.'))renderVariety();
 if(tab==='production'&&(path.startsWith('studio.budgets.')||path.startsWith('jobs.')))renderProduction();
});
document.addEventListener('input',e=>{
 const el=e.target;
 if(['review-draft','review-time','review-end'].includes(el.id))captureReviewDraft();
 if(el.id==='compare-scrub'){pauseCompare();alignCompare(Number(el.value));$('#compare-clock').textContent=fmt(Number(el.value))+' · paused comparison';}
 for(const [key,axis] of [['takeZoom','scale'],['takePanX','x'],['takePanY','y']])if(el.dataset[key]!==undefined){const i=el.dataset[key],v=$('#take-'+i);if(v){v.dataset[axis]=el.value;v.style.transform=`scale(${v.dataset.scale||1})`;v.style.transformOrigin=`${v.dataset.x||50}% ${v.dataset.y||35}%`;}}
});
document.addEventListener('click',e=>{
 if(e.target.closest('[data-energy-map]')){const r=e.target.closest('[data-energy-map]').getBoundingClientRect(),time=StudioCore.clamp((e.clientX-r.left)/r.width,0,1)*duration(),energy=Math.round(StudioCore.clamp(6-(e.clientY-r.top)/r.height*6,1,5));studioData().music.energy.push({id:id(),time:Math.round(time*1000)/1000,energy,label:''});deskChanged();}
});
document.addEventListener('pointerdown',e=>{
 const marker=e.target.closest('[data-drag-kind]'),svg=e.target.closest('[data-camera-map]');
 if(marker&&svg){e.preventDefault();rememberEdit();const p=shotData(deskScene()).camera[marker.dataset.dragKind][Number(marker.dataset.index)];deskDrag={kind:'camera',svg,marker,point:p,startX:p.x,startY:p.y,pointer:e.pointerId};svg.setPointerCapture(e.pointerId);}
 const overlay=e.target.closest('#review-overlay.drawing');if(overlay){e.preventDefault();const r=overlay.getBoundingClientRect();deskDrag={kind:'annotation',svg:overlay,pointer:e.pointerId,x:StudioCore.clamp((e.clientX-r.left)/r.width,0,1),y:StudioCore.clamp((e.clientY-r.top)/r.height,0,1)};overlay.setPointerCapture(e.pointerId);}
});
document.addEventListener('pointermove',e=>{if(!deskDrag||deskDrag.pointer!==e.pointerId)return;const d=deskDrag,r=d.svg.getBoundingClientRect(),x=StudioCore.clamp((e.clientX-r.left)/r.width,0,1),y=StudioCore.clamp((e.clientY-r.top)/r.height,0,1);if(d.kind==='camera'){d.point.x=Math.round(x*100);d.point.y=Math.round(y*100);d.marker.setAttribute('transform',`translate(${(d.point.x-d.startX)*6},${(d.point.y-d.startY)*3.6})`);}else{d.annotation={x:(d.x+x)/2,y:(d.y+y)/2,rx:Math.max(.005,Math.abs(d.x-x)/2),ry:Math.max(.005,Math.abs(d.y-y)/2)};d.svg.innerHTML=reviewPinSvg([...reviewPins,d.annotation]);}});
function endDeskDrag(e){if(!deskDrag||deskDrag.pointer!==e.pointerId)return;const d=deskDrag;deskDrag=null;if(d.kind==='camera'){changed();renderCamera();}else if(d.annotation){reviewPins.push(d.annotation);d.svg.innerHTML=reviewPinSvg(reviewPins);captureReviewDraft();}}
document.addEventListener('pointerup',endDeskDrag);document.addEventListener('pointercancel',endDeskDrag);

document.addEventListener('focusin',e=>{if(e.target.id==='review-draft'){const v=$('#cut-player');if(v&&!v.paused){v.pause();$('#review-time').value=v.currentTime.toFixed(3);}}});
